/**
 * admin-dashboard-data — read endpoint for the founder-only admin business
 * dashboard (Flutter `/admin` route, web-only).
 *
 * Auth (mirrors promote-community-item's audited v8 gate, diagnose 7ad0c5):
 *   1. Service-role caller (signature-verified via isAuthorizedCronCall) — passes.
 *   2. Authenticated JWT whose user.id is in ADMIN_USER_IDS — passes.
 *   Everything else (anon, authenticated non-admin, missing/invalid token)
 *   returns 403. ADMIN_USER_IDS unset -> fail-secure, reject every caller.
 *
 * Data sources:
 *   - admin_metrics_daily (migration 102) — last 30 days, for trend charts.
 *   - public.founder_metrics_for_admin_api() (migration 101) — current
 *     growth/subscription counts (wraps the existing private.founder_metrics()).
 *   - subscriptions.plan breakdown (live query, ~11 rows today) — for the
 *     derived-MRR calc; not in the daily snapshot since the plan only
 *     promised a *current* MRR figure, not a trend, for v1.
 *   - subscriptions latest active end_date per user (live, derived — OI-202;
 *     the `users.subscription_expires_at` mirror column is dropped) plus
 *     users.email for the rows inside the window — expiring/expired lists.
 *   - alerts table (live query) — reused as-is for the Ops Health feed.
 */

import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import { clientError, corsHeaders, ok, serverError } from "../_shared/error.ts";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import { fetchAllByIds } from "../_shared/paged_fetch.ts";
import { fetchLatestActiveEndByUser, usersWithLatestEndIn } from "../_shared/subscription.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

// Admin allowlist — same env var promote-community-item already depends on
// (verify it's populated before deploying; don't create a duplicate secret).
const ADMIN_USER_IDS = (Deno.env.get("ADMIN_USER_IDS") ?? "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

const TREND_DAYS = 30;
const EXPIRY_WINDOW_DAYS = 30;
const MONTHLY_PRICE_INR = 349;
const YEARLY_PRICE_INR = 2999;

/** Pure — no I/O. Fail-secure: an empty allowlist rejects every authenticated caller. */
export function isAuthorizedAdminCaller(opts: {
  isServiceRole: boolean;
  userId: string | null;
  adminUserIds: string[];
}): boolean {
  if (opts.isServiceRole) return true;
  if (opts.userId == null) return false;
  if (opts.adminUserIds.length === 0) return false;
  return opts.adminUserIds.includes(opts.userId);
}

export interface ExpirySubscriptionRow {
  user_id: string;
  email: string | null;
  subscription_expires_at: string;
}

export interface ExpiryBuckets {
  expired: ExpirySubscriptionRow[];
  expiring7d: ExpirySubscriptionRow[];
  expiring30d: ExpirySubscriptionRow[];
}

/** Pure — takes `now` as a parameter so it never reads the system clock itself. */
export function bucketSubscriptionsByExpiry(
  rows: ExpirySubscriptionRow[],
  now: Date,
): ExpiryBuckets {
  const buckets: ExpiryBuckets = { expired: [], expiring7d: [], expiring30d: [] };
  const in7d = now.getTime() + 7 * 24 * 60 * 60 * 1000;
  const in30d = now.getTime() + 30 * 24 * 60 * 60 * 1000;
  for (const row of rows) {
    const expiresAt = new Date(row.subscription_expires_at).getTime();
    if (expiresAt <= now.getTime()) {
      buckets.expired.push(row);
    } else if (expiresAt <= in7d) {
      buckets.expiring7d.push(row);
    } else if (expiresAt <= in30d) {
      buckets.expiring30d.push(row);
    }
    // Beyond 30 days out: not shown on this tab, intentionally.
  }
  return buckets;
}

/**
 * OI-202 — the expiring/expired list, DERIVED from `subscriptions` (each user's
 * LATEST `status='active'` end_date in `[floorIso, windowIso]`) plus
 * `users.email` for those users. Replaces the read of the dropped
 * `users.subscription_expires_at` mirror column.
 *
 * `null` = the subscriptions read FAILED (the caller must fail the request,
 * never render it as an empty list). A failure of the email lookup throws.
 * A renewed user (a later active row) is outside the window and so is never
 * listed as lapsed.
 */
export async function loadExpiryRows(
  // deno-lint-ignore no-explicit-any
  admin: any,
  floorIso: string,
  windowIso: string,
): Promise<ExpirySubscriptionRow[] | null> {
  const latestEnd = await fetchLatestActiveEndByUser(admin, floorIso);
  if (latestEnd === null) return null;
  const inWindow = usersWithLatestEndIn(
    latestEnd,
    new Date(floorIso),
    new Date(windowIso),
    true,
  );
  // Email lives on `users`; fetched only for the (small) in-window set, in
  // paged id-chunks so neither the URL nor db-max-rows can clip it.
  const emailRows = await fetchAllByIds<{ id: string; email: string | null }>(
    (idChunk) => admin.from("users").select("id, email").in("id", idChunk),
    inWindow.map(([uid]) => uid),
    { orderBy: "id", label: "admin-dashboard-data expiry emails" },
  );
  const emailById = new Map(emailRows.map((r) => [r.id, r.email]));
  return inWindow.map(([uid, endIso]) => ({
    user_id: uid,
    email: emailById.get(uid) ?? null,
    subscription_expires_at: endIso,
  }));
}

export interface PlanCounts {
  monthlyActive: number;
  yearlyActive: number;
  trialActive: number;
  otherActive: number;
}

/**
 * Pure. Buckets active-subscription rows by plan. `monthly` / `yearly` are
 * the paying plans; `referral_trial` is a non-paying trial (surfaced so the
 * split reconciles against the active-sub count); anything else falls into
 * `otherActive` so a future unforeseen plan value is visible, never silently
 * dropped. monthlyActive + yearlyActive + trialActive + otherActive == rows.length.
 */
export function bucketActivePlans(
  rows: Array<{ plan: string | null }>,
): PlanCounts {
  const counts: PlanCounts = {
    monthlyActive: 0,
    yearlyActive: 0,
    trialActive: 0,
    otherActive: 0,
  };
  for (const row of rows) {
    if (row.plan === "monthly") counts.monthlyActive++;
    else if (row.plan === "yearly") counts.yearlyActive++;
    else if (row.plan === "referral_trial") counts.trialActive++;
    else counts.otherActive++;
  }
  return counts;
}

/** Pure. Standard MRR convention: annual plans normalized to a monthly-equivalent (÷12). Trials pay 0. */
export function computeDerivedMrr(
  counts: { monthlyActive: number; yearlyActive: number },
  prices: { monthlyInr: number; yearlyInr: number },
): number {
  return counts.monthlyActive * prices.monthlyInr +
    counts.yearlyActive * (prices.yearlyInr / 12);
}

export const handler = async (req: Request): Promise<Response> => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  if (req.method !== "POST") {
    return clientError("Method not allowed", 405);
  }

  const authHeader = req.headers.get("Authorization") ?? "";
  if (!authHeader.startsWith("Bearer ")) {
    return clientError("Missing authorization header", 401);
  }
  const token = authHeader.slice("Bearer ".length);

  const admin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Resolve identity inside a fail-CLOSED try: a transient GoTrue/network
  // reject on getUser must return a sanitized 500 WITH corsHeaders (via
  // serverError), not bubble out of `serve` as a bare CORS-less 500 that the
  // web dashboard reads as an opaque network error (Hermes L21). It also
  // never fails OPEN — an exception can't reach the admin check below.
  let isServiceRole = false;
  let userId: string | null = null;
  try {
    isServiceRole = await isAuthorizedCronCall(req);
    if (!isServiceRole) {
      const { data } = await admin.auth.getUser(token);
      userId = data?.user?.id ?? null;
    }
  } catch (err) {
    return serverError("admin-dashboard-data:auth", err);
  }

  if (!isAuthorizedAdminCaller({ isServiceRole, userId, adminUserIds: ADMIN_USER_IDS })) {
    if (ADMIN_USER_IDS.length === 0) {
      console.error("[admin-dashboard-data] ADMIN_USER_IDS env var not set; rejecting caller by default");
    } else if (userId) {
      console.warn(`[admin-dashboard-data] non-admin caller rejected: user_id=${userId}`);
    }
    return clientError("Admin only", 403);
  }

  try {
    const now = new Date();
    const dayMs = 24 * 60 * 60 * 1000;
    // Expiry window is BOUNDED on both sides: [now-30d, now+30d]. Without a
    // lower bound the "expired" bucket swept EVERY historically-lapsed user
    // forever — unbounded growth, over-exposed emails, no LIMIT (Hermes
    // L1/L21/L37/L40 all flagged it). "Expired" now means "lapsed in the last
    // 30 days" — the actionable win-back set, not all-time history.
    const expiryFloorIso = new Date(now.getTime() - EXPIRY_WINDOW_DAYS * dayMs)
      .toISOString();
    const expiryWindowIso = new Date(now.getTime() + EXPIRY_WINDOW_DAYS * dayMs)
      .toISOString();

    // `current` is LIVE across ALL three metric groups (growth + engagement +
    // ops), same as the growth tab already was — the daily snapshot table is
    // ONLY for the historical `trend` series. Before Hermes L1-F1 the
    // engagement/ops "today" tiles read `trend.last` (up to 24h stale, or 0
    // before the first nightly snapshot); now they read a genuinely-live value.
    const [trendRes, growthRes, engagementRes, opsRes, planRes, expiryRes, alertsRes] =
      await Promise.all([
        admin
          .from("admin_metrics_daily")
          .select("*")
          .order("snapshot_date", { ascending: false })
          .limit(TREND_DAYS),
        admin.rpc("founder_metrics_for_admin_api").single(),
        admin.rpc("founder_metrics_engagement").single(),
        admin.rpc("founder_metrics_ops").single(),
        admin.from("subscriptions").select("plan").eq("status", "active"),
        // OI-202: derived from `subscriptions` (null = the read failed —
        // handled below).
        loadExpiryRows(admin, expiryFloorIso, expiryWindowIso),
        admin
          .from("alerts")
          .select("id, detected_at, source, severity, summary, suggested_action")
          .is("resolved_at", null)
          .order("detected_at", { ascending: false })
          .limit(20),
      ]);

    const firstError = trendRes.error || growthRes.error || engagementRes.error ||
      opsRes.error || planRes.error || alertsRes.error ||
      // A failed expiry read must fail the request like every sibling read,
      // never render as "nobody is expiring".
      (expiryRes === null ? new Error("subscriptions latest-end read failed") : null);
    if (firstError) {
      return serverError("admin-dashboard-data", firstError);
    }

    // Plan split across ACTIVE subscriptions. Live distinct values
    // (2026-07-13): {monthly, referral_trial}; `yearly` has 0 rows today
    // but is a valid future plan. referral_trial subs are NOT paying, so
    // they contribute 0 to MRR but MUST be surfaced — otherwise the tab
    // shows "1 monthly, 0 yearly" against 7 active subs with 6 unexplained.
    // `otherActive` is a catch-all so a future unforeseen plan value can
    // never silently re-open that gap (monthly+yearly+trial+other == active).
    const planCounts = bucketActivePlans(
      (planRes.data ?? []) as Array<{ plan: string | null }>,
    );

    const expiryRows = expiryRes as ExpirySubscriptionRow[];
    const expiryBuckets = bucketSubscriptionsByExpiry(expiryRows, now);

    const derivedMrr = computeDerivedMrr(planCounts, {
      monthlyInr: MONTHLY_PRICE_INR,
      yearlyInr: YEARLY_PRICE_INR,
    });

    return ok({
      generated_at: now.toISOString(),
      trend: trendRes.data ?? [],
      // Merge the three live metric-group rows into one `current` object.
      // Each carries its own `generated_at`; the spread keeps the last
      // (ops) one — the model only reads the top-level `generated_at`, so
      // the collision is harmless.
      current: {
        ...(growthRes.data as Record<string, unknown> ?? {}),
        ...(engagementRes.data as Record<string, unknown> ?? {}),
        ...(opsRes.data as Record<string, unknown> ?? {}),
      },
      revenue: {
        monthly_active: planCounts.monthlyActive,
        yearly_active: planCounts.yearlyActive,
        trial_active: planCounts.trialActive,
        other_active: planCounts.otherActive,
        derived_mrr_inr: derivedMrr,
        current_monthly_price_inr: MONTHLY_PRICE_INR,
        current_yearly_price_inr: YEARLY_PRICE_INR,
      },
      subscriptions_expiring: expiryBuckets,
      open_alerts: alertsRes.data ?? [],
    });
  } catch (err) {
    return serverError("admin-dashboard-data", err);
  }
};

if (import.meta.main) {
  serve(handler);
}

// Shared error sanitization for Edge Functions.
//
// Rule: the client NEVER sees raw exception messages, stack traces, upstream
// provider responses, SQL hints, or environment-shaped strings. Unexpected
// failures are logged server-side with full detail and returned to the client
// as a generic `Internal server error` plus a request_id the user can quote
// when contacting support.
//
// Intentional 4xx validation errors (e.g. "Message too long", "Snapshot too
// large", "Image too large", "Only Supabase Storage URLs are allowed", "PRO
// subscription required") are kept verbatim and should NOT flow through this
// helper. Use `clientError()` to return those directly with the correct
// status code.

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
};

/**
 * Generate a short, URL-safe request id for correlating client-reported
 * failures to server logs. Not cryptographically significant — just enough
 * entropy to disambiguate concurrent requests.
 */
export function newRequestId(): string {
  // crypto.randomUUID is available in Deno runtime
  const uuid = crypto.randomUUID();
  // Return first 8 chars — plenty for log lookup, short enough to quote.
  return uuid.split("-")[0];
}

/**
 * Build a sanitised 5xx response. Logs full details to stderr; returns a
 * generic body to the client with a request_id they can quote.
 *
 * @param context short string identifying the Edge Function / operation
 * @param err the caught error (any type)
 * @param extraHeaders optional additional headers to merge with corsHeaders
 */
export function serverError(
  context: string,
  err: unknown,
  extraHeaders: Record<string, string> = {},
): Response {
  const requestId = newRequestId();
  const detail = err instanceof Error
    ? { message: err.message, stack: err.stack, name: err.name }
    : { value: String(err) };
  // Full detail stays on the server — ops, logs, Sentry, whatever.
  console.error(
    `[${context}] request_id=${requestId}`,
    JSON.stringify(detail),
  );
  return new Response(
    JSON.stringify({
      error: "Internal server error",
      request_id: requestId,
    }),
    {
      status: 500,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * Build a 4xx response with a client-safe message. Use this for validation
 * errors (bad input, auth failures, quota exceeded, etc.) where the user
 * NEEDS the specific message to know what to do. Always safe — callers are
 * expected to pass only vetted, non-leaking strings.
 */
export function clientError(
  message: string,
  status: number,
  extraHeaders: Record<string, string> = {},
): Response {
  return new Response(
    JSON.stringify({ error: message }),
    {
      status,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * Convenience: JSON success response with CORS.
 */
export function ok(
  body: unknown,
  extraHeaders: Record<string, string> = {},
): Response {
  return new Response(
    JSON.stringify(body),
    {
      status: 200,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/json",
        ...extraHeaders,
      },
    },
  );
}

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
// Exported (review round 1 F11) so telegram-admin-bot's webhook-secret
// comparison — the ONLY gate on that publicly-reachable endpoint, same
// threat model as the 16+ cron-secret-gated endpoints this was written
// for — can reuse it instead of a bare `!==`.
export async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

/**
 * paged_fetch — bounded reads for cron Edge Functions (OI-79).
 *
 * ## The bug this exists to prevent
 *
 * PostgREST caps every response at `db-max-rows` (1000 on this project) and
 * **supabase-js gives you no way to notice**. Measured live 2026-08-01 against
 * `dedsavbjuwgarrhphgnl`, `food_database` (1431 rows):
 *
 * | request                                   | status | Content-Range | rows |
 * |-------------------------------------------|--------|---------------|------|
 * | `?select=id` (what `.select()` sends)      | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 0-1499`                            | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 1000-1999`                         | 200 OK | `1000-1430/*` |  431 |
 * | `Prefer: count=exact`                      | 206    | `0-999/1431`  | 1000 |
 *
 * Three things follow, and each one is load-bearing:
 *
 * 1. **It is a 200, not a 206.** OI-79 was filed saying truncation shows up as
 *    `206 Partial Content`. That is only true when the caller asks for a count,
 *    and no cron function here does. In the shape our code actually sends, the
 *    response is a plain `200 OK` with a short body and `error === null`. There
 *    is no status, no error, and no total (`/*`) to compare against — a
 *    truncated read is *byte-for-byte indistinguishable* from a small one. The
 *    only signal is the row count, and it is AMBIGUOUS: a page shorter than
 *    `pageSize` means either end-of-data or a server cap below `pageSize`.
 *    That is why the loop terminates on an EMPTY page, never a short one.
 * 2. **`.range()` cannot raise the cap.** Asking for 0-1499 still yields 1000.
 *    So `pageSize` MUST be <= the cap; a larger value does not fetch more, it
 *    silently breaks the loop (you ask for 1500, get 1000, read that as a short
 *    page, and stop early — dropping every row after the first page).
 * 3. **Paging past the cap works.** Offset 1000-1999 returns the remainder.
 *    A `.range()` loop is therefore a real fix, not a workaround.
 *
 * ## Why `orderBy` is required and has no default
 *
 * Postgres guarantees no row order without an `ORDER BY`, and PostgREST adds
 * none. Two `.range()` calls against an unordered relation may return
 * overlapping or disjoint slices, so a paginated loop without a stable sort key
 * can **duplicate or skip rows** — silently, and only under load. Three loops in
 * this repo shipped that way (`morning-alert`, `weekly-recap-ready`,
 * `weekly-recalc`); `i-see-you-callout` got it right with
 * `.order("id", { ascending: true })`. Making `orderBy` a required parameter
 * with no default is how that mistake becomes unconstructible here.
 *
 * Pick a key that is **unique and immutable** — a primary key. A non-unique key
 * (`date`, `status`) does not fully order the rows, so ties can shuffle between
 * page requests and reintroduce the same skip/duplicate bug.
 *
 * ## RPCs
 *
 * `.order()` / `.range()` are accepted on `/rpc/` set-returning functions, so
 * both helpers work with `() => supabase.rpc(...)`. Whether `db-max-rows` also
 * caps RPC responses could not be settled from here: the only anon-executable
 * set-returning functions on this project are not `SECURITY DEFINER`, so RLS
 * returns 0 rows to `anon` and the probe is inconclusive. It does not change
 * anything — these helpers page unconditionally, which is correct either way
 * (if the cap does not apply, the loop simply ends on the first empty page).
 *
 * @see docs/audit/open_issues.md OI-79
 */

// deno-lint-ignore-file no-explicit-any

/**
 * PostgREST's server-side `db-max-rows` for this project, confirmed live
 * (table above). A response can never exceed this many rows regardless of the
 * requested `Range`.
 */
export const POSTGREST_MAX_ROWS = 1000;

/** Default page size. Sits at the cap: the largest value that is still safe. */
export const DEFAULT_PAGE_SIZE = 1000;

/**
 * Default `.in()` chunk size. Bounds the **request URL**, which is a different
 * constraint from `pageSize` (which bounds the *response*). A uuid costs ~37
 * bytes in `in.(...)`, so 100 ids is ~3.7KB and stays clear of the ~4-8KB URL
 * limits proxies impose. Matches the existing `BATCH_SIZE = 100` precedent in
 * `evaluate-rank-promotions`.
 */
export const DEFAULT_CHUNK_SIZE = 100;

/**
 * Runaway guard. At the default page size this permits 10M rows, far beyond any
 * legitimate cron scan — it exists to turn "PostgREST keeps returning full
 * pages forever" (an unstable sort key, a clock-skewed filter) into a loud
 * failure instead of an Edge Function that runs until the platform kills it.
 */
export const DEFAULT_MAX_PAGES = 10_000;

/** Minimal structural shape we need from a supabase-js query builder. */
interface RangeableBuilder {
  order(column: string, opts: { ascending: boolean }): RangeableBuilder;
  range(from: number, to: number): PromiseLike<{ data: unknown; error: unknown }>;
}

/** One ORDER BY term. */
export interface OrderKey {
  column: string;
  ascending?: boolean;
}

export interface PagedFetchOptions {
  /**
   * REQUIRED. Sort key — must be unique and immutable (a primary key). See the
   * header note on why this has no default.
   *
   * Pass an array to sort by several columns, e.g. to page a "most recent row
   * per user" read while preserving its ordering semantics:
   * `[{ column: "snapshot_date", ascending: false }, { column: "id" }]`.
   * The **last** term must be unique — the earlier ones can tie, and ties
   * without a unique tiebreaker are exactly the unstable-page bug.
   */
  orderBy: string | OrderKey[];
  /**
   * Sort direction for the single-column form. Ignored when `orderBy` is an
   * array (each term carries its own).
   */
  ascending?: boolean;
  /** Rows per request. MUST be <= {@link POSTGREST_MAX_ROWS}; see header note 2. */
  pageSize?: number;
  /** Runaway guard, see {@link DEFAULT_MAX_PAGES}. */
  maxPages?: number;
  /** Prefix for the saturation log line. Defaults to "paged_fetch". */
  label?: string;
}

/** Normalises the `orderBy` union into a non-empty list of ORDER BY terms. */
function orderKeys(opts: PagedFetchOptions): OrderKey[] {
  const bad = () => {
    throw new Error(
      "paged_fetch: `orderBy` is required and must be a non-empty column name " +
        "(or a non-empty array of them). A .range() loop without a stable sort " +
        "key can skip or duplicate rows (OI-79).",
    );
  };

  if (typeof opts.orderBy === "string") {
    if (!opts.orderBy.trim()) bad();
    return [{ column: opts.orderBy, ascending: opts.ascending ?? true }];
  }
  if (!Array.isArray(opts.orderBy) || opts.orderBy.length === 0) bad();
  const keys = (opts.orderBy as OrderKey[]).map((k) => {
    if (!k || typeof k.column !== "string" || !k.column.trim()) bad();
    return { column: k.column, ascending: k.ascending ?? true };
  });
  return keys;
}

function validate(opts: PagedFetchOptions): { pageSize: number; maxPages: number } {
  orderKeys(opts); // throws when the sort key is missing or malformed
  const pageSize = opts.pageSize ?? DEFAULT_PAGE_SIZE;
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new Error(`paged_fetch: pageSize must be a positive integer, got ${pageSize}`);
  }
  if (pageSize > POSTGREST_MAX_ROWS) {
    throw new Error(
      `paged_fetch: pageSize ${pageSize} exceeds PostgREST's db-max-rows ` +
        `(${POSTGREST_MAX_ROWS}). A larger page cannot fetch more rows — the server ` +
        `silently clamps it — so every page costs a full round-trip for at most ` +
        `${POSTGREST_MAX_ROWS} rows while the arithmetic implies more. The loop itself is ` +
        `SAFE at any cap (it advances by rows received and stops only on an empty page), ` +
        `so this is a wrong-configuration guard, not a correctness one. ` +
        `Use a pageSize <= ${POSTGREST_MAX_ROWS} (OI-79).`,
    );
  }
  const maxPages = opts.maxPages ?? DEFAULT_MAX_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new Error(`paged_fetch: maxPages must be a positive integer, got ${maxPages}`);
  }
  return { pageSize, maxPages };
}

/**
 * Reads **every** row matching a query, paging until an EMPTY page arrives.
 *
 * `makeQuery` must return a fresh builder each call — supabase-js builders are
 * single-use thenables, so reusing one across pages does not work. Apply your
 * filters there and let this apply `.order()` and `.range()`:
 *
 * ```ts
 * const rows = await fetchAllPages<{ user_id: string }>(
 *   () => supabase.from("coach_memory").select("user_id").gte("dropout_risk_score", 0.5),
 *   { orderBy: "user_id", label: "re-engagement path A" },
 * );
 * ```
 *
 * Throws on the first page error rather than returning partial rows. That is
 * deliberate: silently proceeding with an incomplete candidate set is the exact
 * failure this module exists to prevent, and a cron tick that cannot read its
 * inputs should fail loudly and retry on the next tick.
 */
export async function fetchAllPages<T>(
  makeQuery: () => unknown,
  opts: PagedFetchOptions,
): Promise<T[]> {
  const { pageSize, maxPages } = validate(opts);
  const keys = orderKeys(opts);
  const label = opts.label ?? "paged_fetch";
  const keyDesc = keys.map((k) => `${k.column}${k.ascending ? "" : " desc"}`).join(", ");

  const all: T[] = [];

  for (let page = 0; ; page++) {
    if (page >= maxPages) {
      throw new Error(
        `paged_fetch[${label}]: exceeded maxPages=${maxPages} (${all.length} rows read). ` +
          `Every page came back full — check that orderBy='${keyDesc}' ends in a unique, ` +
          `immutable column; an unstable sort key can loop forever.`,
      );
    }

    // Offset by rows ACTUALLY received, never by `page * pageSize`. The two
    // agree only while the server serves full pages, and `db-max-rows` is a
    // dashboard setting (Settings -> API -> Max rows), not a platform
    // invariant. Lower it to 500 and the old arithmetic broke completely:
    // page 0 asked 0-999, got 500, and `500 < pageSize` read as end-of-data —
    // so every one of the reads this module was written to fix would silently
    // return 500 rows with error === null. Advancing by `all.length` makes the
    // loop correct for ANY server cap without having to know what it is.
    const from = all.length;
    const to = from + pageSize - 1;

    let q = makeQuery() as RangeableBuilder;
    for (const k of keys) q = q.order(k.column, { ascending: k.ascending ?? true });
    const builder = q.range(from, to);

    const { data, error } = await builder;
    if (error) {
      throw new Error(
        `paged_fetch[${label}]: page ${page} (rows ${from}-${to}) failed: ` +
          `${(error as { message?: string } | null)?.message ?? String(error)}`,
      );
    }

    const rows = (data ?? []) as T[];
    all.push(...rows);

    // Only an EMPTY page proves end-of-data. A SHORT page does not: it is
    // equally the signature of a server cap below `pageSize` (see the offset
    // note above), and treating it as "done" is exactly the silent truncation
    // this module exists to prevent.
    //
    // COST, stated honestly. For `fetchAllPages` this is one extra round-trip
    // per read. For `fetchAllByIds` it is one extra per CHUNK, and with
    // DEFAULT_CHUNK_SIZE = 100 a chunk essentially never fills a 1000-row
    // page — so the confirming request lands on ~every chunk, not on a rare
    // boundary. 12 chunked call sites; at ~10k PRO users protein-gap-alert
    // goes from roughly 300 to 600 sequential round-trips per tick. Accepted
    // deliberately: these are daily cron jobs where wall-clock is cheap, and
    // the alternative is a read that silently returns half its rows with
    // error === null. If round-trips ever become the constraint, learn the
    // server's real page size once per process instead. (Corrected after
    // round-2 review — the earlier note claimed "the same one the
    // exact-multiple case already paid", true of fetchAllPages and NOT of the
    // chunked path that dominates.)
    if (rows.length === 0) break;
  }

  return all;
}

/**
 * Reads every row for a set of ids, chunking the `.in()` list **and** paging
 * within each chunk.
 *
 * Chunking alone is not enough, and that distinction is the whole point of this
 * function. `evaluate-rank-promotions` already had a `fetchInChunks` helper that
 * split `userIds` into batches of 100 — but a chunk bounds the *request*, not
 * the *response*. One 100-id chunk against a table holding N rows per user
 * returns 100xN rows, so it truncates at 10 rows/user no matter how small the
 * chunk is. This pages inside each chunk, which bounds both.
 *
 * ```ts
 * const logs = await fetchAllByIds<{ user_id: string }>(
 *   (chunk) => supabase.from("nutrition_logs")
 *                      .select("user_id, total_protein")
 *                      .eq("date", todayIST)
 *                      .in("user_id", chunk),
 *   proUserIds,
 *   { orderBy: "id", label: "protein-gap-alert nutrition" },
 * );
 * ```
 */
export async function fetchAllByIds<T>(
  makeQuery: (idChunk: string[]) => unknown,
  ids: string[],
  opts: PagedFetchOptions & { chunkSize?: number },
): Promise<T[]> {
  validate(opts);

  const chunkSize = opts.chunkSize ?? DEFAULT_CHUNK_SIZE;
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new Error(`paged_fetch: chunkSize must be a positive integer, got ${chunkSize}`);
  }

  if (ids.length === 0) return [];

  const all: T[] = [];
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    const rows = await fetchAllPages<T>(() => makeQuery(chunk), {
      ...opts,
      label: `${opts.label ?? "paged_fetch"} chunk@${i}`,
    });
    all.push(...rows);
  }
  return all;
}

/**
 * subscription.ts — the single definition of "is this user PRO".
 *
 * Added 2026-07-26 (diagnose <id>). Before this, every Edge Function that
 * needed PRO status hand-rolled the predicate. Five distinct variants existed
 * across the codebase, and one of them was wrong in a way that cost money.
 *
 * THE PREDICATE
 * -------------
 *   subscriptions.status = 'active'  AND  end_date > now()
 *
 * BOTH terms are required. `status` is NEVER reconciled to 'expired' by any
 * job, cron or trigger — so rows sit at `status='active'` with an end_date
 * months in the past, indefinitely. A status-only check treats every one of
 * them as PRO.
 *
 * This is not hypothetical. At the time of writing, live production held 5
 * `status='active'` rows and **zero** of them were unexpired; the newest had
 * expired 13 days earlier. A status-only check would have reported 4 PRO
 * users where the correct answer is 0.
 *
 * WHY THERE IS NO `users.subscription_status` / `users.subscription_expires_at`
 * -----------------------------------------------------------------------------
 * Those two denormalized mirror columns (and the `update_user_subscription_status`
 * trigger + `extend_subscription` RPC that wrote them) were DROPPED by migration
 * 152 (OI-202). The mirror carried no expiry term and nothing wrote it back to
 * 'free', so it drifted from the truth by construction: live it claimed 6 PRO
 * users, all 6 lapsed, and `morning-alert` read it and sent Gemini-generated
 * PRO-tier copy to churned users -- paid tokens spent on people who had stopped
 * paying, and the churn signal destroyed. Migration 093 had called that column
 * "the canonical PRO gate" while ai-proxy called the `subscriptions` predicate
 * canonical: two canonical answers that disagreed by 6 users.
 *
 * THE `subscriptions` TABLE IS THE ONLY SOURCE. Anything that used to read the
 * mirror for a per-user expiry ("who lapses / expires soon") reads
 * `fetchLatestActiveEndByUser` below instead.
 */

import { fetchAllPages } from "./paged_fetch.ts";

// deno-lint-ignore no-explicit-any
type SupabaseLike = any;

/// Sanity ceiling on the batch fetch — see the canary in fetchProUserIds.
/// NOT a query limit: the read is paged (OI-79), so this is a "that number
/// looks wrong" tripwire rather than a cap that silently discards rows.
const _proFetchCap = 5000;

/**
 * The set of user_ids that are PRO right now.
 *
 * Use this when you have a batch of users to classify — one query for the
 * whole run, then O(1) membership checks. Do NOT call `isProUser` in a loop.
 *
 * Returns an EMPTY SET on query error, never throws. Callers must treat that
 * as "nobody is PRO" — the fail-safe direction, since the alternative is
 * sending paid-tier content to unknown users.
 */
export async function fetchProUserIds(
  client: SupabaseLike,
): Promise<Set<string>> {
  try {
    // OI-79 — the `.limit(_proFetchCap)` (5000) this replaces was UNREACHABLE:
    // PostgREST caps every response at db-max-rows (1000), so the read silently
    // stopped at 1000 active PRO users and every one past that was treated as
    // free. Worse, the `rows.length >= _proFetchCap` guard below could never
    // fire — a saturation detector that is structurally always false is more
    // dangerous than none, because it reads as "we would have been told".
    // Paged, so `_proFetchCap` is now a real ceiling the loop can actually reach.
    // Pin the cutoff ONCE, outside the per-page closure. `fetchAllPages` calls
    // the closure again for every page, so an inline `new Date()` would re-run
    // per request and each page would be offset into a DIFFERENT result set: a
    // subscription expiring mid-scan shrinks the set, every later row shifts
    // down one, and the row at that boundary is never returned. That silently
    // drops a paying user from a PRO *inclusion* set — the same Class-1
    // "silently wrong" outcome this batch exists to remove, re-entered through
    // the predicate instead of the sort key.
    const cutoffIso = new Date().toISOString();
    const data = await fetchAllPages<{ user_id: string }>(
      () =>
        client
          .from("subscriptions")
          .select("user_id")
          .eq("status", "active")
          .gt("end_date", cutoffIso),
      { orderBy: "id", pageSize: 1000, label: "subscription pro-user-ids" },
    );

    const rows = data ?? [];
    // Canary — now genuinely reachable. Before OI-79 this compared against a
    // 5000 cap on a read PostgREST clipped at 1000, so it could never fire
    // however many PRO users existed: the very truncation it was written to
    // announce would silently happen 4000 rows below the threshold. Paging
    // removes the 1000 ceiling, so exceeding _proFetchCap is once again a real
    // condition worth shouting about (an unexpectedly huge PRO base, or a
    // filter that stopped filtering).
    if (rows.length >= _proFetchCap) {
      console.warn(
        `[subscription] fetchProUserIds returned ${rows.length} rows, at or ` +
          `above the ${_proFetchCap} sanity ceiling — check the status/end_date ` +
          `filter before trusting this PRO set.`,
      );
    }
    return new Set<string>(rows.map((r: { user_id: string }) => r.user_id));
  } catch (err) {
    // The `{ data, error }` shape catches API-level failures, but a
    // transport-level fetch rejection (DNS, reset, timeout before any HTTP
    // response) may reject the promise instead. Without this catch that would
    // propagate into morning-alert's single outer try and abort the whole
    // nightly run for every user — not just skip the PRO/free split. Cheap to
    // rule out, and it makes the "never throws" contract above literally true.
    console.error("[subscription] fetchProUserIds threw:", err);
    return new Set<string>();
  }
}

/**
 * True when this one user is PRO right now.
 *
 * For a single user only — in a loop use `fetchProUserIds` instead.
 * Returns false on error, never throws (fail-safe, as above).
 */
export async function isProUser(
  client: SupabaseLike,
  userId: string,
): Promise<boolean> {
  try {
    const { data, error } = await client
      .from("subscriptions")
      .select("user_id")
      .eq("user_id", userId)
      .eq("status", "active")
      .gt("end_date", new Date().toISOString())
      .limit(1);

    if (error) {
      console.error("[subscription] isProUser failed:", error.message);
      return false;
    }
    return (data ?? []).length > 0;
  } catch (err) {
    // Same transport-rejection reasoning as fetchProUserIds above.
    console.error("[subscription] isProUser threw:", err);
    return false;
  }
}


/**
 * One `subscriptions` row as `fetchLatestActiveEndByUser` reads it.
 * `end_date` is a timestamptz, returned by PostgREST as an ISO-8601 string.
 */
export interface ActiveSubscriptionEndRow {
  user_id: string;
  end_date: string;
}

/**
 * PURE. Reduces subscription rows to the LATEST `end_date` per user.
 *
 * A user can hold several `status='active'` rows across a renewal (live
 * evidence, 2026-09: 7 active rows for 5 users), so "the user's expiry" is the
 * max over their rows -- NOT the value of an arbitrary one. Compared by parsed
 * instant, not by string, because PostgREST may render the same instant with
 * `+00:00` or `Z` and a lexical compare would then order them wrongly. Rows
 * whose `end_date` does not parse are skipped rather than allowed to poison the
 * comparison (`NaN > x` is always false, which would silently keep the FIRST
 * row seen).
 *
 * Deliberately has no try/catch: every returned value has exactly one source,
 * so a test asserting on it cannot be satisfied by an exception handler.
 */
export function reduceLatestEndByUser(
  rows: readonly ActiveSubscriptionEndRow[],
): Map<string, string> {
  const latest = new Map<string, { iso: string; ms: number }>();
  for (const r of rows) {
    const ms = Date.parse(r.end_date);
    if (Number.isNaN(ms)) continue;
    const cur = latest.get(r.user_id);
    if (cur === undefined || ms > cur.ms) {
      latest.set(r.user_id, { iso: r.end_date, ms });
    }
  }
  const out = new Map<string, string>();
  for (const [uid, v] of latest) out.set(uid, v.iso);
  return out;
}

/**
 * PURE. The users whose LATEST active end_date falls in `[from, to)`, or
 * `[from, to]` when `toInclusive` is set. Returns `[user_id, end_date]` pairs.
 *
 * Because the input is already reduced to the latest end per user, a user who
 * renewed (an old row lapsing in the window AND a newer row ending after it) is
 * correctly NOT reported as lapsing or expiring.
 */
export function usersWithLatestEndIn(
  latestEndByUser: ReadonlyMap<string, string>,
  from: Date,
  to: Date,
  toInclusive = false,
): Array<[string, string]> {
  const fromMs = from.getTime();
  const toMs = to.getTime();
  const out: Array<[string, string]> = [];
  for (const [uid, iso] of latestEndByUser) {
    const ms = Date.parse(iso);
    if (Number.isNaN(ms)) continue;
    if (ms < fromMs) continue;
    if (toInclusive ? ms > toMs : ms >= toMs) continue;
    out.push([uid, iso]);
  }
  return out;
}

/**
 * The latest `status='active'` `end_date` per user, for every user whose latest
 * end is at or after `sinceIso`. `null` on ANY read failure.
 *
 * `sinceIso` is a floor, not a page filter: filtering rows by `end_date >= since`
 * before taking the per-user max is exact for users whose global max is >= since
 * (the max row survives the filter) and simply omits the rest -- which is what a
 * caller asking "who ends after X" wants. It also bounds the scan: a
 * years-old lapsed row is never fetched.
 *
 * NULL, NOT AN EMPTY MAP, ON ERROR -- the opposite of `fetchProUserIds`. There an
 * empty set is the fail-safe direction ("nobody is PRO"); here an empty map
 * would read as "no one is expiring" / "no one lapsed", a confident and wrong
 * number in a founder digest. Callers MUST branch on `null` and surface an
 * unreadable section.
 *
 * Paged (OI-79) with a cutoff pinned by the caller, so every page is cut from
 * the same result set.
 */
export async function fetchLatestActiveEndByUser(
  client: SupabaseLike,
  sinceIso: string,
): Promise<Map<string, string> | null> {
  let rows: ActiveSubscriptionEndRow[];
  try {
    rows = await fetchAllPages<ActiveSubscriptionEndRow>(
      () =>
        client
          .from("subscriptions")
          .select("user_id, end_date")
          .eq("status", "active")
          .gte("end_date", sinceIso),
      {
        orderBy: "id",
        pageSize: 1000,
        label: "subscription latest-active-end-by-user",
        // Bounded like every other digest/bot read (MAX_PAGES = 200 in
        // founder_digest_content.ts): /expiring and /digest run this inside a
        // Telegram webhook, where a slow scan outlasts the timeout and
        // triggers a duplicate update (Hermes L21 2026-09-29).
        maxPages: 200,
      },
    ) ?? [];
  } catch (err) {
    console.error("[subscription] fetchLatestActiveEndByUser threw:", err);
    return null;
  }
  // Sanity tripwire, like fetchProUserIds': there is no upper bound on end_date
  // here, so an unexpectedly large active base (or a filter that stopped
  // filtering) should be loud, not silent (Hermes L23 2026-09-29).
  if (rows.length >= _proFetchCap) {
    console.warn(
      `[subscription] fetchLatestActiveEndByUser returned ${rows.length} rows, ` +
        `at or above the ${_proFetchCap} sanity ceiling — check the filter.`,
    );
  }
  // Reduced OUTSIDE the try: a bug in the reducer must not be mistaken for a
  // read failure and swallowed into `null`.
  return reduceLatestEndByUser(rows);
}
